class nglTexture;
class PhotoChallenge {
public:
    int GetNumTaken(void);
    nglTexture *GetPhotoTexture(int);
    int *GetPhotoScore(int);
};
class BeachChallenges {
public:
    PhotoChallenge *photo;
};
class beach {
public:
    BeachChallenges *get_challenges(void);
};
extern beach *g_beach_ptr;
class FEMenuEntry {
public:
    FEMenuEntry *next;
    void Disable(bool);
};
class FEMultiMenu {
    char layout[0x44];
public:
    FEMenuEntry *entries;
    void OnActivate(void);
    void Right(void);
};
class PhotoWidget {
    char layout[0x104];
public:
    void Show(nglTexture *, int *, int, float);
};
class PanelQuad;
class TextString;
class PhotoSelectMenu : public FEMultiMenu {
private:
    PanelQuad *arrowPQs[2][2];
    PanelQuad *highlightPQs[3];
    PhotoWidget photoWidgets[3];
    TextString *title;
    int leftArrowIdx, rightArrowIdx;
    float arrowHiTimer;
    int highlightedIdx;
public:
    void OnActivate(void);
    void setHigh(FEMenuEntry *, bool = true);
};

void PhotoSelectMenu::OnActivate(void)
{
    PhotoChallenge *photoChallenge = g_beach_ptr->get_challenges()->photo;
    float fade;
    int hiIdx = 0;
    int i;

    FEMultiMenu::OnActivate();

    if (photoChallenge->GetNumTaken() > 0)
    {
        fade = 0.0f;
        entries->Disable(false);
    }
    else
    {
        fade = 1.0f;
        entries->Disable(true);
    }
    photoWidgets[0].Show(photoChallenge->GetPhotoTexture(0), photoChallenge->GetPhotoScore(0), 0, fade);

    if (photoChallenge->GetNumTaken() > 1)
    {
        fade = 0.0f;
        entries->next->Disable(false);
    }
    else
    {
        fade = 1.0f;
        entries->next->Disable(true);
    }
    photoWidgets[1].Show(photoChallenge->GetPhotoTexture(1), photoChallenge->GetPhotoScore(1), 1, fade);

    if (photoChallenge->GetNumTaken() > 2)
    {
        fade = 0.0f;
        entries->next->next->Disable(false);
    }
    else
    {
        fade = 1.0f;
        entries->next->next->Disable(true);
    }
    photoWidgets[2].Show(photoChallenge->GetPhotoTexture(2), fade == 1.0f ? 0 : photoChallenge->GetPhotoScore(2), 2, fade);

    for (i = 1; i < 3; i++)
    {
        if (*photoChallenge->GetPhotoScore(i) > *photoChallenge->GetPhotoScore(hiIdx))
            hiIdx = i;
    }
    setHigh(entries);
    for (i = 0; i < hiIdx; i++)
        FEMultiMenu::Right();
}
